mapper.select:
SELECT a.id AS officeId, a.name AS officeName, a.type AS officeType FROM sys_office a WHERE a.del_flag = '0' AND a.name IN
#{name}
ORDER BY a.name, a.id LIMIT 21

SELECT DISTINCT a.HD_ID

ORDER BY a.HD_ID
LIMIT #{limit}

SELECT EXISTS(
    SELECT 1 FROM expense_calendar_info e
    WHERE e.expense_stationCode = #{stationCode}
      AND e.expense_state = '10'
      AND e.del_flag = '0'
)
